2	/**
3	 * Moves the claim to the action's status; refused (400) when the claim's status does not allow it.
4	 * Opening gives the claim the sheet's next number; a voided claim keeps its number (it is never reused). While the
5	 * sheet's period numbering from date is set and its today is on or after it, opening instead gives the claim the next
6	 * number within the period containing its date (P1-1, P1-2, ...), or within the claims in no period (X-1, ...).
7	 * Opening records the user who opened it; that user cannot settle it (four eyes). A deferred claim cannot be settled.
8	 * Settling fixes the claim's due at its person's grade's rate in force on the claim's date, raised to the sheet's floor and rounded by its policy date — or, when a statement
9	 * bound the claim, at the figure it was bound to — plus the late charge it has then, if overdue, frozen in; with no
10	 * figure it stays live. A clerk settling a claim whose due is above the sheet's clerk limit (a due of n/a is within any
11	 * limit) makes it PENDING instead, live and unfixed. Only a steward approves a PENDING claim (fixing its due at its live
12	 * figure, plus any late charge, at that moment) — not the user who opened it — or rejects it, with a reason, back to OPEN.
13	 * Only a steward re-settles a SETTLED claim, fixing its due again at the figure it would have today as an open claim
14	 * bound by no statement (today's rates, grades, floor and late charge); its previous due is kept for the audit.
15	 */
16	public class ApplyClaimAction {
17	    public void apply(@PathVariable("action") String action, @RequestParam("user") String user, @Val Claim claim,
18	            @Val ClaimActionRequest request, SheetRepository sheets,
19	            PersonRepository people, RateRepository rates, SettingRepository settings, PeriodRepository periods,
20	            ClaimRepository claims, Out<ClaimAction> applied, Out<ClaimNumber> number, Out<PreviousDue> previous, Out<Claim> updated) throws InvalidClaimException {
21	        ClaimAction found = ClaimAction.of(action);
22	        if (found == null) {
23	            throw new InvalidClaimException("No such claim action: " + action);
24	        }
25	        if (!found.allowedFrom(claim.status())) {
26	            throw new InvalidClaimException("A " + claim.status() + " claim cannot be " + found.to() + ".");
27	        }
28	        if (found == ClaimAction.SETTLE && claim.deferred(sheets.today(claim.sheetId()))) {
29	            throw new InvalidClaimException("The claim is deferred until " + claim.deferredUntil() + ": it cannot be settled yet.");
30	        }
31	        if (found == ClaimAction.SETTLE && user.equals(claim.openedBy())) {
32	            throw new InvalidClaimException("The user who opened a claim cannot settle it.");
33	        }
34	        if (found == ClaimAction.APPROVE && user.equals(claim.openedBy())) {
35	            throw new InvalidClaimException("The user who opened a claim cannot approve it.");
36	        }
37	        if ((found == ClaimAction.APPROVE || found == ClaimAction.REJECT)
38	                && settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
39	            throw new InvalidClaimException("Only a steward can " + action + " a pending claim.");
40	        }
41	        if (found == ClaimAction.RESETTLE && settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
42	            throw new InvalidClaimException("Only a steward can re-settle a settled claim.");
43	        }
44	        if (found == ClaimAction.REJECT && request.reason().isEmpty()) {
45	            throw new InvalidClaimException("A reason is required to reject a claim.");
46	        }
47	        BigDecimal due = found.settles() ? settledDue(found == ClaimAction.RESETTLE ? claim.asOpenUnbound() : claim, sheets, people, rates, settings, claims) : claim.due();
48	        if (found == ClaimAction.SETTLE && !settings.find(claim.sheetId()).maySettle(user, due)) {
49	            found = ClaimAction.PEND;
50	            due = null;
51	        }
52	        String next = switch (found) {
53	            case OPEN -> nextNumber(claim, sheets, settings, periods);
54	            default -> claim.number();
55	        };
56	        applied.set(found);
57	        previous.set(new PreviousDue(claim.due()));
58	        number.set(new ClaimNumber(next));
59	        updated.set(claim.withStatus(found.to(), next, due, found == ClaimAction.OPEN ? user : claim.openedBy()));
60	    }
61	    private static String nextNumber(Claim claim, SheetRepository sheets, SettingRepository settings,
62	            PeriodRepository periods) {
63	        LocalDate from = settings.periodNumberingFrom(claim.sheetId());
64	        if (from == null || sheets.today(claim.sheetId()).isBefore(from)) {
65	            return String.valueOf(sheets.nextClaimNumber(claim.sheetId()));
66	        }
67	        Period period = periods.findAll(claim.sheetId()).stream().filter((p) -> p.contains(claim.date())).findFirst()
68	                .orElse(null);
69	        String prefix = period == null ? "X" : period.name();
70	        String key = period == null ? "" : period.name().toLowerCase();
71	        return prefix + "-" + sheets.nextPeriodClaimNumber(claim.sheetId(), key);
72	    }
73	    private static BigDecimal settledDue(Claim claim, SheetRepository sheets, PersonRepository people,
74	            RateRepository rates, SettingRepository settings, ClaimRepository claims) {
75	        return ClaimDueNow.of(claim, sheets, people, rates, settings, claims);
76	    }
77	}
