648	/**
649	 * What an overdue claim is charged: the late percent in force on its date of its figure for every full 30 days it is overdue
650	 * (its due-by, fixed when it was created, before the sheet's today), rounded like the claim's due. Never bound by a statement:
651	 * it follows the sheet's today until the claim is settled. A correction, and a deferred claim, is never charged.
652	 */
653	public record LateCharge(BigDecimal pct, LocalDate today) {
654	    /** The days in each period an overdue claim is charged for. */
655	    public static final int PERIOD_DAYS = 30;
656	    /** The charge on the claim's figure (null: n/a, charged nothing); zero unless the claim is overdue. */
657	    public BigDecimal on(Claim claim, BigDecimal figure, RoundingMode mode) {
658	        if (figure == null || !claim.status().open() || claim.deferred(today) || claim.correction()) {
659	            return BigDecimal.ZERO.setScale(2);
660	        }
661	        long late = ChronoUnit.DAYS.between(claim.dueBy(), today);
662	        long periods = late > 0 ? late / PERIOD_DAYS : 0;
663	        return Claim.due(figure, pct.multiply(BigDecimal.valueOf(periods)), mode);
664	    }
665	}
