538	/**
539	 * Works out a sheet's figures as the screen shows them: a person's claimed is their counting claims' amounts
540	 * added up; their due-total those claims' dues (live figures raised to the floor in force on each claim's date and rounded by its policy date, plus
541	 * any late charge, at the late percent in force on its date, on the overdue ones) added up, at most the cap in force on the sheet's today; n/a when their grade on the sheet's today has no
542	 * rate there and no counting claim has a figure (kept, or at the rate for the grade in force on its date). Their overdue-total
543	 * is the dues of their overdue counting claims added up (skipping n/a, not capped). The sheet's totals add these up, skipping n/a.
544	 */
545	@Service
546	public class RollupService {
547	    private static final String NA = "n/a";
548	    private final PersonRepository people;
549	    private final ClaimRepository claims;
550	    private final RateRepository rates;
551	    private final SheetRepository sheets;
552	    private final SettingRepository settings;
553	    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
554	            SheetRepository sheets, SettingRepository settings) {
555	        this.people = people;
556	        this.claims = claims;
557	        this.rates = rates;
558	        this.sheets = sheets;
559	        this.settings = settings;
560	    }
561	    /** The sheet's figures as the store holds them now. */
562	    public Rollup compute(String sheetId) {
563	        LocalDate today = sheets.today(sheetId);
564	        List<Rate> sheetRates = rates.findAll(sheetId);
565	        DatedSettings dated = settings.dated(sheetId);
566	        BigDecimal cap = dated.capOn(today);
567	        List<Claim> sheetClaims = claims.findAll(sheetId);
568	        Rounding rounding = settings.rounding(sheetId, today, sheetClaims);
569	        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
570	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
571	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
572	        BigDecimal overdueTotal = BigDecimal.ZERO.setScale(2);
573	        for (Person person : people.findAll(sheetId)) {
574	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
575	            BigDecimal due = BigDecimal.ZERO.setScale(2);
576	            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
577	            boolean kept = false;
578	            for (Claim claim : sheetClaims) {
579	                if (claim.personId() != person.id() || !person.counts(claim, today)) {
580	                    continue;
581	                }
582	                claimed = claimed.add(claim.amount());
583	                kept |= claim.keepsFigure();
584	                BigDecimal figure = claim.due(Rate.inForce(sheetRates, person.gradeOn(claim.date()), claim.date()),
585	                        dated.floorOn(claim.date()), dated.lateCharge(claim.date(), today), rounding);
586	                if (figure != null) {
587	                    kept = true;
588	                    due = due.add(figure);
589	                    if (claim.overdue(today)) {
590	                        overdue = overdue.add(figure);
591	                    }
592	                }
593	            }
594	            boolean na = Rate.inForce(sheetRates, person.grade(), today) == null && !kept;
595	            due = Cap.apply(cap, due);
596	            claimedTotal = claimedTotal.add(claimed);
597	            if (!na) {
598	                dueTotal = dueTotal.add(due);
599	            }
600	            overdueTotal = overdueTotal.add(overdue);
601	            figures.put(person.id(), new Rollup.Figures(person.name(), show(claimed), na ? NA : show(due), show(overdue)));
602	        }
603	        return new Rollup(figures, show(claimedTotal), show(dueTotal), show(overdueTotal));
604	    }
605	    private static String show(BigDecimal value) {
606	        return value.setScale(2).toPlainString();
607	    }
608	}
