642	        BigDecimal total = BigDecimal.ZERO.setScale(2);
643	        boolean kept = false;
644	        int counted = 0;
645	        List<Claim> personClaims = claims.findForPerson(person.sheetId(), person.id());
646	        Rounding rounding = settings.rounding(person.sheetId(), today, personClaims);
647	        for (Claim claim : personClaims) {
648	            if (!person.counts(claim, today)) {
649	                claims.bindStatement(claim, false, null);
650	                continue;
651	            }
652	            boolean fixed = claim.keepsFigure();
653	            BigDecimal figure = claim.figure(Rate.inForce(sheetRates, person.gradeOn(claim.date()), claim.date()),
654	                    dated.floorOn(claim.date()), rounding);
