681	/**
682	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
683	 * so tests can assert side-effects by reading that file — the second test-assertion channel
684	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
685	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
686	 *
687	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
688	 * SYNC) so a test reads the record immediately.
689	 */
690	@Service
691	public class Audit {
692	    private final Path file;
693	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
694	        this.file = Path.of(path);
695	    }
696	    /** Append one audit record. Tests assert the exact line(s) in the file. */
697	    public synchronized void record(String entry) {
698	        try {
699	            Path parent = file.toAbsolutePath().getParent();
700	            if (parent != null) {
701	                Files.createDirectories(parent);
702	            }
703	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
704	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
705	        } catch (IOException e) {
706	            throw new UncheckedIOException(e);
707	        }
708	    }
709	    /** Remove the audit file. */
710	    public synchronized void clear() {
711	        try {
712	            Files.deleteIfExists(file);
713	        } catch (IOException e) {
714	            throw new UncheckedIOException(e);
715	        }
716	    }
717	}
