499	    /**
500	     * The grade's rate in force on the date: the one with the latest from-date on or before it, unless its to-date
501	     * is before the date; null with none.
502	     */
503	    public static BigDecimal inForce(List<Rate> rates, String grade, LocalDate date) {
504	        return rates.stream()
505	                .filter((r) -> r.grade().equals(grade) && (r.from() == null || !r.from().isAfter(date)))
506	                .max(Comparator.comparing(Rate::from, Comparator.nullsFirst(Comparator.naturalOrder())))
507	                .filter((r) -> r.to() == null || !r.to().isBefore(date))
508	                .map(Rate::rate).orElse(null);
509	    }
510	}
