106	/**
107	 * Closes the period, fixing its due-total as it stands now: the dues (figures plus any late charge) of the counting
108	 * claims dated in it, added up (n/a skipped), and each person's share of it (0.00 for a person with none). Refused (400) when it is already closed.
109	 */
110	public class ClosePeriod {
111	    public void close(@Val Period period, ClaimRepository claims, PersonRepository people, RateRepository rates,
112	            SettingRepository settings, SheetRepository sheets, Out<Period> closed) throws InvalidPeriodException {
113	        if (period.closed()) {
114	            throw new InvalidPeriodException("The period " + period.name() + " is already closed.");
115	        }
116	        Map<Long, Person> byId = people.findAll(period.sheetId()).stream()
117	                .collect(Collectors.toMap(Person::id, Function.identity()));
118	        List<Rate> sheetRates = rates.findAll(period.sheetId());
119	        DatedSettings dated = settings.dated(period.sheetId());
120	        LocalDate today = sheets.today(period.sheetId());
121	        List<Claim> sheetClaims = claims.findAll(period.sheetId());
122	        Rounding rounding = settings.rounding(period.sheetId(), today, sheetClaims);
123	        BigDecimal total = BigDecimal.ZERO.setScale(2);
124	        Map<Long, BigDecimal> perPerson = new HashMap<>();
125	        for (Long id : byId.keySet()) {
126	            perPerson.put(id, BigDecimal.ZERO.setScale(2));
127	        }
128	        for (Claim claim : sheetClaims) {
129	            Person person = byId.get(claim.personId());
130	            if (person == null || !person.counts(claim, today) || !period.contains(claim.date())) {
131	                continue;
132	            }
133	            BigDecimal figure = claim.due(Rate.inForce(sheetRates, person.gradeOn(claim.date()), claim.date()),
134	                    dated.floorOn(claim.date()), dated.lateCharge(claim.date(), today), rounding);
135	            if (figure != null) {
136	                total = total.add(figure);
137	                perPerson.merge(person.id(), figure, BigDecimal::add);
138	            }
139	        }
140	        closed.set(period.close(total, perPerson));
141	    }
142	}
