=== rates/rates.ts
/**
 * A grade's rate as the store holds it: a percent with two decimals, in force from its from-date
 * (yyyy-MM-dd; null: from the beginning of time) until the grade's next rate takes over, or through its
 * to-date (null: no end), whichever comes first.
 */
export type Rate = { grade: string; rate: string; from: string | null; to: string | null };
/** The fields the rate form submits; a blank from-date is from the beginning of time, a blank to-date no end. */
export type RateInput = { grade: string; rate: string; from: string; to: string };
/** What a due shows when its grade has no rate. */
export const NA = 'n/a';
/** 0.00 or more, with at most two decimals. */
export const PERCENT = /^(\d{1,5}(\.\d{1,2})?|\.\d{1,2})$/;
/** The query key for the sheet's rates; under sheetKey, so re-loading the sheet re-reads them. */
export const ratesKey = (sheet: string) => [...sheetKey(sheet), 'rates'] as const;
/** The sheet's rates, by grade and then from-date (from the start first). */
export function useRates() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: ratesKey(sheet),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates`),
    enabled: !!sheet,
  });
}
/**
 * The grade's rate (two decimals) in force on the date: the one with the latest from-date on or
 * before it, a rate with no from-date applying from the start; undefined when none applies, or when that
 * one's to-date is before the date.
 */
export function rateFor(rates: Rate[], grade: string | undefined, date: string): string | undefined {
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (!found || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  if (found?.to != null && found.to < date) return undefined;
  return found?.rate;
}
/** A two-decimal value as whole hundredths, exactly. */
const hundredths = (value: string) => Math.round(Number(value) * 100);
/** How a half is rounded: half up (away from zero) or half to even. */
export type Rounding = 'half-up' | 'half-even';
/**
 * How a claim's live figures round: half up when it is dated before the sheet's policy date, half to
 * even on or after it. A correction rounds by the date of the claim it corrects, not its own.
 */
export function roundingFor(claim: Claim, rules: DueRules): Rounding {
  const date = claim.corrects !== null ? (rules.claimDates.get(claim.corrects) ?? claim.date) : claim.date;
  return date < rules.policyDate ? 'half-up' : 'half-even';
}
/**
 * An amount times a percent rate, divided by 100, rounded to two decimals (half to even unless told
 * otherwise); n/a with no rate. Worked in whole hundredths so it is exact: cents × basis points / 10000.
 */
export function due(amount: string, rate: string | undefined, rounding: Rounding = 'half-even'): string {
  if (rate === undefined) return NA;
  return percentOf(hundredths(amount), hundredths(rate), rounding);
}
/** Cents times basis points / 10000, rounded to two decimals as told. */
function percentOf(amountCents: number, basisPoints: number, rounding: Rounding): string {
  const product = amountCents * basisPoints;
  const whole = Math.floor(Math.abs(product) / 10000);
  const rest = Math.abs(product) - whole * 10000;
  const up = rest > 5000 || (rest === 5000 && (rounding === 'half-up' || whole % 2 === 1));
  const cents = Math.sign(product) * (whole + (up ? 1 : 0));
  return (cents / 100).toFixed(2);
}
/** A live due raised to the floor (both two decimals); n/a stays n/a. */
export function floored(value: string, floor: string): string {
  return value !== NA && hundredths(value) < hundredths(floor) ? Number(floor).toFixed(2) : value;
}
/**
 * A claim's figure: the figure its statement bound it to (not while PENDING), else its amount at the rate in force on its
 * date for the person's grade in force on that date, rounded by the policy date, at least the floor in force on its date —
 * a correction has no floor.
 */
function claimFigure(claim: Claim, rates: Rate[], grades: GradeFrom[], rules: DueRules): string {
  if (bound(claim)) return claim.statedDue ?? NA;
  const live = due(claim.amount, rateFor(rates, gradeOn(grades, claim.date), claim.date), roundingFor(claim, rules));
  return claim.corrects !== null ? live : floored(live, rules.floorOn(claim.date));
}
/**
 * The late charge on a figure: the late percent in force on the claim's date of it for every full 30 days the claim is overdue,
 * rounded like the claim's due; 0.00 when it is not overdue, and always for a correction.
 */
export function lateCharge(claim: Claim, figure: string, rules: DueRules): string {
  if (claim.corrects !== null) return '0.00';
  const periods = latePeriods(claim, rules.today);
  return percentOf(hundredths(figure), hundredths(rules.latePctOn(claim.date)) * periods, roundingFor(claim, rules));
}
/**
 * A claim's due: the one fixed when it was settled (any late charge frozen in), else its figure plus
 * the late charge on it while it is overdue. The charge is never bound by a statement: it follows the
 * sheet's today.
 */
export function claimDue(claim: Claim, rates: Rate[], grades: GradeFrom[], rules: DueRules): string {
  if (claim.due !== null) return claim.due;
  const figure = claimFigure(claim, rates, grades, rules);
  return figure === NA ? NA : total([figure, lateCharge(claim, figure, rules)]);
}
/** Whether a claim keeps a figure whatever the rates: fixed when settled, or bound by a statement. */
const keepsFigure = (c: Claim) => c.due !== null || (bound(c) && c.statedDue !== null);
/**
 * A person's due-total: the figures of their claims that count, added up (0.00 with none). With no
 * rate in force on the sheet's today for their grade on that day it is n/a, unless a claim has a figure (kept
 * when settled or stated, or at the rate for the grade in force on its date): then it is the figures there are,
 * added up. Their open claims a hold covers (not bound by a statement) do not count. It is at most the
 * sheet's cap (n/a is not capped).
 */
export function personDue(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  holds: Hold[],
  rules: DueRules,
): string {
  const sum = personSum(claims, rates, grades, holds, rules);
  if (sum === NA || rules.cap === '' || hundredths(sum) <= hundredths(rules.cap)) return sum;
  return rules.cap;
}
/** A person's excess: by how much their due-total is above the sheet's cap; 0.00 when it is not (or is n/a). */
export function personExcess(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  holds: Hold[],
  rules: DueRules,
): string {
  const sum = personSum(claims, rates, grades, holds, rules);
  if (sum === NA || rules.cap === '') return '0.00';
  return (Math.max(0, hundredths(sum) - hundredths(rules.cap)) / 100).toFixed(2);
}
/** A person's due-total before the cap: their counting claims' figures added up, or n/a. */
function personSum(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  holds: Hold[],
  rules: DueRules,
): string {
  const counted = claims.filter((c) => counts(c, holds, rules.today));
  const figures = counted.map((c) => claimDue(c, rates, grades, rules));
  const anyFigure = counted.some(keepsFigure) || figures.some((f) => f !== NA);
  if (rateFor(rates, gradeOn(grades, rules.today), rules.today) === undefined && !anyFigure) {
    return NA;
  }
  return total(figures);
}
/** Dues added up, skipping n/a; with two decimals, added in cents so it is exact. */
export function total(dues: string[]): string {
  const cents = dues.filter((d) => d !== NA).reduce((sum, d) => sum + hundredths(d), 0);
  return (cents / 100).toFixed(2);
}
=== overdue/overdue.ts
export { overdue } from './dueBy';
/**
 * A person's overdue claims that count (none of their open ones a hold covers): how many, and
 * their dues (late charges included) added up (skipping n/a).
 */
export function personOverdue(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  holds: Hold[],
  rules: DueRules,
): { count: number; total: string } {
  const late = claims.filter((c) => counts(c, holds, rules.today) && overdue(c, rules.today));
  return { count: late.length, total: total(late.map((c) => claimDue(c, rates, grades, rules))) };
}
=== overdue/dueBy.ts
/** Whether a claim is overdue: it is OPEN (or PENDING), not deferred, and its due-by, fixed when it was created, is before the sheet's today. */
export function overdue(claim: Claim, today: string): boolean {
  return isOpen(claim) && !deferred(claim, today) && today !== '' && claim.dueBy < today;
}
/** How many full 30-day periods a claim is overdue on the sheet's today: 0 unless it is overdue. */
export function latePeriods(claim: Claim, today: string): number {
  if (!overdue(claim, today)) return 0;
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${claim.dueBy}T00:00:00Z`)) / 86_400_000;
  return Math.floor(Math.round(days) / 30);
}
=== claims/claims.ts
/**
 * Where a claim is in its life: DRAFT -> OPEN -> SETTLED; a clerk's settle above the clerk limit makes it
 * PENDING, which a steward approves (SETTLED) or rejects (OPEN); DRAFT, OPEN or PENDING -> VOID.
 */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';
/** Whether a claim is open: OPEN, or PENDING (handled like an open claim). */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';
/**
 * Whether a claim is deferred on the sheet's `today`: OPEN, deferred until a date after it. A deferred claim counts
 * in no total, is not overdue, cannot be settled and is left unbound by a statement.
 */
export const deferred = (c: Claim, today: string) =>
  c.status === 'OPEN' && c.deferredUntil !== null && today !== '' && today < c.deferredUntil;
/** Whether a statement binds the claim now: it was stated and is not PENDING (a pending claim shows its live figure). */
export const bound = (c: Claim) => c.stated && c.status !== 'PENDING';
/**
 * A claim as the store holds it: the amount with two decimals, the date as yyyy-MM-dd; its number
 * is the sheet's next one when it was opened (1, 2, ...; under period numbering, the next within its period: P1-1, X-1), null while a draft (a voided claim keeps it); its due is the
 * one fixed when it was settled (two decimals), null while it is live; openedBy is the user who
 * opened it, null while a draft; stated is whether its person's last statement bound it to a figure,
 * statedDue that figure (two decimals; null: n/a) — it then shows and totals that, not its live figure;
 * corrects is, for a correction (a negative amount), the number of the settled claim it corrects, null otherwise;
 * dueBy (yyyy-MM-dd) is fixed when it was created: its date plus the terms of its person's grade in force on it;
 * log is its status log, oldest first: each status it has had, the user who gave it, the sheet's today then and its due then;
 * deferredUntil (yyyy-MM-dd) is the date it was deferred until, null when it never was.
 */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  dueBy: string;
  log: ClaimLogLine[];
  deferredUntil: string | null;
};
/** A line of a claim's status log: the status, the user, the sheet's today (yyyy-MM-dd) and the due then (two decimals, or n/a). */
export type ClaimLogLine = { status: ClaimStatus; by: string; date: string; due: string };
/**
 * Whether a claim counts toward claimed, due-total and every live total: only OPEN, PENDING and SETTLED do,
 * and an open (or pending) one not when one of its person's `holds` covers its date and no statement binds it,
 * nor while it is deferred on the sheet's `today`.
 */
export const counts = (c: Claim, holds: Hold[], today: string) =>
  c.status === 'SETTLED' ||
  (isOpen(c) && !deferred(c, today) && (bound(c) || !holds.some((h) => covers(h, c.date))));
/** Each person's holds, by id: their open claims dated within one count in no live total. */
export const holdsById = (people: { id: number; holds: Hold[] }[]) => new Map(people.map((p) => [p.id, p.holds]));
/** The fields the claim form submits; a blank date is the sheet's today; corrects names, by number, the claim a correction corrects. */
export type ClaimInput = { amount: string; date: string; note: string; corrects: string };
/** 0.00 or more, with at most two decimals. */
export const AMOUNT = /^(\d+(\.\d{1,2})?|\.\d{1,2})$/;
/** An amount the claim form takes: negative for a correction, with at most two decimals. */
export const SIGNED_AMOUNT = /^-?(\d+(\.\d{1,2})?|\.\d{1,2})$/;
/** The query key for the sheet's claims; under sheetKey, so re-loading the sheet re-reads them. */
export const claimsKey = (sheet: string) => [...sheetKey(sheet), 'claims'] as const;
/** The sheet's claims, newest first. */
export function useClaims() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: claimsKey(sheet),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/claims`),
    enabled: !!sheet,
  });
}
/** The sum of the counted claims' amounts, with two decimals; added in cents so it is exact. `holds` holds each person's holds. */
export function claimed(claims: Claim[], holds: Map<number, Hold[]>, today: string): string {
  const cents = claims.filter((c) => counts(c, holds.get(c.personId) ?? [], today)).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
=== periods/periods.ts
/**
 * A period as the store holds it: its name (unique on the sheet), its from and to dates (yyyy-MM-dd),
 * both inclusive, whether it is closed and, when closed, the due-total fixed then (null while open) and each
 * person's due-total fixed then, by person id (empty while open).
 */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string | null;
  personTotals: Record<string, string>;
};
/** The fields the period form submits. */
export type PeriodInput = { name: string; from: string; to: string };
/** The query key for the sheet's periods; under sheetKey, so re-loading the sheet re-reads them. */
export const periodsKey = (sheet: string) => [...sheetKey(sheet), 'periods'] as const;
/** The sheet's periods, earliest first. */
export function usePeriods() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: periodsKey(sheet),
    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`),
    enabled: !!sheet,
  });
}
/** Whether the date (yyyy-MM-dd) falls in the period, both ends included. */
export const contains = (p: Period, date: string) => p.from <= date && date <= p.to;
/** The period whose dates contain the date; undefined with none. Periods never overlap, so there is at most one. */
export const periodOf = (periods: Period[], date: string) => periods.find((p) => contains(p, date));
/**
 * A person's due-total for a period: the dues (late charges included) of their claims that count whose date falls
 * in it (open ones a hold covers left out), added up; a closed period keeps the figure fixed when it was closed
 * (0.00 for a person added since).
 */
export function personPeriodDue(period: Period, person: Person, claims: Claim[], rates: Rate[], rules: DueRules): string {
  if (period.closed) return period.personTotals?.[String(person.id)] ?? '0.00';
  const figures = claims
    .filter((c) => c.personId === person.id && counts(c, person.holds, rules.today) && contains(period, c.date))
    .map((c) => claimDue(c, rates, person.grades, rules));
  return total(figures);
}
/** A period's due-total: the people's due-totals for it, added up. */
export function periodDue(period: Period, claims: Claim[], people: Person[], rates: Rate[], rules: DueRules): string {
  return total(people.map((p) => personPeriodDue(period, p, claims, rates, rules)));
}

